prompt --application/shared_components/plugins/dynamic_action/rw_apex_classic_report_sticky_columns
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(44972459459373538969)
,p_plugin_type=>'DYNAMIC ACTION'
,p_name=>'RW.APEX.CLASSIC.REPORT.STICKY.COLUMNS'
,p_display_name=>'APEX Sticky Classic Report Columns'
,p_apexlang_name=>'apexStickyClassicReportColumns'
,p_category=>'STYLE'
,p_image_prefix=>nvl(wwv_flow_application_install.get_static_plugin_file_prefix('DYNAMIC ACTION','RW.APEX.CLASSIC.REPORT.STICKY.COLUMNS'),'')
,p_javascript_file_urls=>'#PLUGIN_FILES#script#MIN#.js'
,p_css_file_urls=>'#PLUGIN_FILES#style#MIN#.css'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function render (',
'    p_dynamic_action in apex_plugin.t_dynamic_action,',
'    p_plugin         in apex_plugin.t_plugin',
') return apex_plugin.t_dynamic_action_render_result is',
'    l_result apex_plugin.t_dynamic_action_render_result;',
'begin',
'    l_result.javascript_function := ''function () { stickyClassicReportColumns(apex, apex.jQuery).initialize( this, {'' ||',
'        apex_javascript.add_attribute(''columnNumber'', p_dynamic_action.attribute_01, false, true) ||',
'        apex_javascript.add_attribute(''maxTableHeight'', p_dynamic_action.attribute_02, false, false) ||',
'    ''}); }'';',
'    return l_result;',
'end;'))
,p_api_version=>1
,p_render_function=>'render'
,p_standard_attributes=>'REGION:REQUIRED:ONLOAD'
,p_substitute_attributes=>true
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>This dynamic action plug-in is for Classic Reports. It ensures that a configured number of columns remain pinned to the left edge when scrolling horizontally. The plug-in should be triggered via the \201CAfter Refresh\201D event on the Classic Report regi')
||'on and "Fire on Page Load" should also be activated.</p>',
'<p>This plug-in does only support UT-Theme and not Redwood light.</p>'))
,p_version_identifier=>'25.02.01'
,p_about_url=>'https://ronnyweiss.app'
,p_files_version=>50
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(44972459705460542864)
,p_plugin_id=>wwv_flow_imp.id(44972459459373538969)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_static_id=>'attribute_01'
,p_prompt=>'Number of sticky Columns'
,p_apexlang_name=>'numberOfStickyColumns'
,p_attribute_type=>'NUMBER'
,p_is_required=>true
,p_default_value=>'1'
,p_is_translatable=>false
,p_help_text=>'Set number of sticky columns.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(44972459940358546199)
,p_plugin_id=>wwv_flow_imp.id(44972459459373538969)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>2
,p_display_sequence=>20
,p_static_id=>'attribute_02'
