prompt --application/shared_components/plugins/item_type/sri_dynamic_text_area_expanding_of_item
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(72313196193632463820)
,p_plugin_type=>'ITEM TYPE'
,p_name=>'SRI.DYNAMIC_TEXT_AREA_EXPANDING_OF_ITEM'
,p_display_name=>'Dynamic Text Area Expanding of Item'
,p_apexlang_name=>'dynamicTextAreaExpandingOfItem'
,p_supported_component_types=>'APEX_APPLICATION_PAGE_ITEMS'
,p_image_prefix=>nvl(wwv_flow_application_install.get_static_plugin_file_prefix('ITEM TYPE','SRI.DYNAMIC_TEXT_AREA_EXPANDING_OF_ITEM'),'')
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/*-------------------------------------',
' * Apex Auto Text Area Expand',
' * Version: 1.0 (12-May-2025)',
' * Author:  Sridhar Thayumanavar',
' *-------------------------------------',
' */',
' ',
' -- Render Procedure',
' PROCEDURE render_auto_textarea_expand (p_item in apex_plugin.t_item,',
'                             p_plugin in apex_plugin.t_plugin,',
'                             p_param in apex_plugin.t_item_render_param,',
'                             p_result in out nocopy apex_plugin.t_item_render_result',
')',
'',
'IS ',
'',
'lv_item_name VARCHAR2(1000) := apex_plugin.get_input_name_for_page_item(false);',
'lv_item_value CLOB := p_param.value;',
'lv_text_align VARCHAR2(100) :=  p_item.attributes.get_varchar2(''text_align'');  ',
'lv_rows        NUMBER := p_item.attributes.get_varchar2(''rows''); ',
'lv_cols       NUMBER := p_item.attributes.get_varchar2(''columns'');',
'ln_max_length NUMBER := p_item.attributes.get_varchar2(''max_length'');',
'lv_err_message VARCHAR(32676) := p_item.attributes.get_varchar2(''error_message'');',
'lv_alert_title VARCHAR(32676) := p_item.attributes.get_varchar2(''alert_title'');',
'lv_alert_ok_label VARCHAR(32676) := p_item.attributes.get_varchar2(''alert_ok_label'');',
'lc_html CLOB; ',
'',
'BEGIN ',
'-- apex_util.set_session_state(lv_item_name,lv_item_value); ',
'',
'if  lv_err_message is null then ',
'lv_err_message := ''This field shouldn''''t allow more than ''||ln_max_length||'' characters.'';',
'end if;',
'',
'-- lc_html := APEX_ITEM.TEXTAREA(p_idx => 1, ',
'--                               p_value => lv_item_value, ',
'--                               p_rows  => lv_rows,',
'--                               p_cols  => lv_cols,',
'--                               p_attributes => '' style="text-align:''||lv_text_align||''"  class = "apex-item-text text_field AutoTextAreaHeight " maxlength = "''||ln_max_length||''" validation="''||lv_err_message||''" alerttitle="''||lv_alert_title||''", '
||'alertoklabel="''||lv_alert_ok_label||''"'', ',
'--                               p_item_id => lv_item_name,',
'--                               p_item_label => NULL); ',
'',
'lc_html :=',
'    ''<textarea ''||',
'    ''id="''||p_item.name||''" ''||',
'    ''name="''||p_item.name||''" ''||',
'    ''rows="''||lv_rows||''" ''||',
'    ''cols="''||lv_cols||''" ''||',
'    ''maxlength="''||ln_max_length||''" ''||',
'    ''class="apex-item-text text_field AutoTextAreaHeight" ''||',
'    ''style="text-align:''||lv_text_align||''" ''||',
'    ''validation="''||lv_err_message||''" ''||',
'    ''alerttitle="''||lv_alert_title||''" ''||',
'    ''alertoklabel="''||lv_alert_ok_label||''">''||',
'    apex_escape.html(lv_item_value)||',
'    ''</textarea>'';',
'',
'',
'   --To add the JavaScript file ',
'    apex_javascript.add_library(p_name        => ''AutoTextArea'',',
'                                p_directory   => p_plugin.file_prefix,',
'                                p_version     => NULL',
'                               );',
'    ',
'    if  lv_err_message is null then ',
'    lv_err_message := ''This field shouldn''''t allow more than ''||ln_max_length||'' characters.'';',
'    end if;',
'    --To fire the JavaScript code on load',
'    apex_javascript.add_onload_code (''AutoExpand.Expand_A()'' );',
'',
'HTP.P(lc_html); ',
'',
'',
'END; '))
,p_api_version=>3
,p_render_function=>'render_auto_textarea_expand'
,p_item_session_state_data_type=>'VARCHAR2'
,p_standard_attributes=>'VISIBLE:FORM_ELEMENT:SESSION_STATE:READONLY:SOURCE:ELEMENT:PLACEHOLDER:ENCRYPT:FILTER'
,p_version_scn=>'SH256:C2MOUEwvN_artRUq4OBFXxCdXA9tNQCeAk6d5n5L9oc'
,p_version_identifier=>'1.0'
,p_files_version=>162
,p_updated_on=>wwv_flow_imp.dz('20260820103440Z')
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
