'select ',
'    ''<b>'' || Attribute_Name || ''</b>'' as Attribute_Name,',
'    Functionality,',
'    Values_1,',
'    seq',
'from(',
'    SELECT ',
'        ''Text Align'' as Attribute_Name,',
'        ''Text alignment'' as Functionality,',
'        ''For Expample : Left, Right, Center. By default Left.'' as Values_1,',
'        1 as seq',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Rows'',',
'        ''To indicate the rows of the Text area.'',',
'        ''1,2,3 .. etc..'',',
'        2',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Columns'',',
'        ''To indicate the columns of the Text area.'',',
'        ''10'',',
'        3',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Maximum Length'',',
'        ''To indicate the maximum length of Text area field.'',',
'        ''10'',',
'        4',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Maximum Letter Length Error Message'',',
'        ''To raise an error when the text area field exceeds the maximum letters.'',',
'        ''10'',',
'        5',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Alert Title'',',
'        ''Title of the Error alert.'',',
'        ''For Example. Warning'',',
'        6',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Alert Ok Label'',',
'        ''Label of the alert button.'',',
'        ''For Example. Okay!'',',
'        7',
'    FROM DUAL',
')',
'order by seq'))
