'',
'    apex_json.open_object;',
'    apex_json.write(''text'', l_user_message);',
'    apex_json.close_object;',
'',
'    apex_json.close_array;',
'    apex_json.close_object;',
'',
'    apex_json.close_array;',
'    apex_json.close_object;',
'',
'    l_payload := apex_json.get_clob_output;',
'    apex_json.free_output;',
'',
'    apex_web_service.g_request_headers.delete;',
'',
'    apex_web_service.g_request_headers(1).name  := ''Content-Type'';',
'    apex_web_service.g_request_headers(1).value := ''application/json'';',
'',
'    l_response := apex_web_service.make_rest_request(',
'        p_url                  => ''https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent'',',
'        p_http_method          => ''POST'',',
'        p_body                 => l_payload,',
'        p_credential_static_id => ''google-gemini-api-credential''',
'    );',
'',
'    if apex_web_service.g_status_code <> 200 then',
'',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(',
'            ''message'',',
'            ''Gemini Error (''||apex_web_service.g_status_code||'') : ''||',
'            dbms_lob.substr(l_response,3000,1)',
'        );',
'        apex_json.close_object;',
'',
'        sys.htp.p(apex_json.get_clob_output);',
'        apex_json.free_output;',
'',
'        return;',
'    end if;',
'',
'    apex_json.parse(l_response);',
'',
'    l_bot_reply :=',
'        apex_json.get_varchar2(',
'            p_path => ''candidates[%d].content.parts[%d].text'',',
'            p0     => 1,',
'            p1     => 1',
'        );',
'',
'    apex_json.initialize_clob_output;',
'',
'    apex_json.open_object;',
'    apex_json.write(''message'', l_bot_reply);',
'    apex_json.close_object;',
'',
'    sys.htp.p(apex_json.get_clob_output);',
'',
'    apex_json.free_output;',
'',
'exception',
'    when others then',
'',
'        apex_json.initialize_clob_output;',
'',
'        apex_json.open_object;',
'        apex_json.write(''message'',''ERROR : ''||sqlerrm);',
'        apex_json.close_object;',
'',
'        sys.htp.p(apex_json.get_clob_output);',
'',
'        apex_json.free_output;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>28667883742402215235
,p_created_on=>wwv_flow_imp.dz('20260820125327Z')
,p_updated_on=>wwv_flow_imp.dz('20260820131848Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
end;
